begin;
with j as (select * from jsonb_to_recordset($law7d0005$[{"code_id":"APK_RF","article_number":"165","version_date":"2002-07-24","article_text":"1. В случае, если арбитражный суд во время или после судебных прений признает необходимым выяснить дополнительные обстоятельства или исследовать новые доказательства, суд возобновляет исследование доказательств, на что указывает в протоколе судебного заседания.\n\n2. После окончания дополнительного исследования доказательств судебные прения происходят в общем порядке, установленном настоящим Кодексом.","article_title":"Статья 165. Возобновление исследования доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5aa2c41238dbb83912e7731f943b0fc6d53d6f9e5ba05738eac7eb3199ea1f2e"},{"code_id":"APK_RF","article_number":"166","version_date":"2002-07-24","article_text":"После исследования доказательств по делу и судебных прений председательствующий в судебном заседании объявляет рассмотрение дела по существу законченным и арбитражный суд удаляется для принятия решения, о чем объявляется присутствующим в зале судебного заседания.","article_title":"Статья 166. Окончание рассмотрения дела по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acf8ab22b4a43a8da6cfa28efb3a474615065a479ebcdb323672e43f1a725fdd"},{"code_id":"APK_RF","article_number":"167","version_date":"2002-07-24","article_text":"1. При разрешении спора по существу арбитражный суд первой инстанции принимает решение. Решение принимается именем Российской Федерации.\n\n2. Арбитражный суд может принять отдельное решение по каждому из требований, объединенных в одном деле.\n\n3. Решение принимается судьями, участвующими в судебном заседании, в условиях, обеспечивающих тайну совещания судей.\n\n4. В помещении, в котором арбитражный суд проводит совещание и принимает судебный акт, могут находиться только лица, входящие в состав суда, рассматривающего дело. Запрещается доступ в это помещение других лиц, а также иные способы общения с лицами, входящими в состав суда.","article_title":"Статья 167. Принятие решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b8c7b2bd2be9791465d865120685f6bf57628cdc31bc4bcdae9760d37e0ce3c"},{"code_id":"APK_RF","article_number":"168","version_date":"2002-07-24","article_text":"1. При принятии решения арбитражный суд оценивает доказательства и доводы, приведенные лицами, участвующими в деле, в обоснование своих требований и возражений; определяет, какие обстоятельства, имеющие значение для дела, установлены и какие обстоятельства не установлены, какие законы и иные нормативные правовые акты следует применить по данному делу; устанавливает права и обязанности лиц, участвующих в деле; решает, подлежит ли иск удовлетворению.\n\n2. При принятии решения арбитражный суд решает вопросы о сохранении действия мер по обеспечению иска или об отмене обеспечения иска либо об обеспечении исполнения решения; при необходимости устанавливает порядок и срок исполнения решения; определяет дальнейшую судьбу вещественных доказательств, распределяет судебные расходы, а также решает иные вопросы, возникшие в ходе судебного разбирательства.\n\n3. Арбитражный суд, признав при принятии решения необходимым дополнительно исследовать доказательства или продолжить выяснение обстоятельств, имеющих значение для дела, возобновляет судебное разбирательство, о чем выносит определение.","article_title":"Статья 168. Вопросы, разрешаемые при принятии решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb26b15d73308774d5af9fadd8196f9e35097e2081b64605159af5ff40c0eb3c"},{"code_id":"APK_RF","article_number":"169","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда излагается в виде отдельного документа.\n\nРешение выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения решения в форме электронного документа решение выполняется на бумажном носителе.\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n2. В решении должны быть указаны мотивы его принятия, и оно должно быть изложено языком, понятным для лиц, участвующих в деле, и других лиц.\n\n3. Решение подписывается судьей, а в случае коллегиального рассмотрения дела - всеми судьями, участвовавшими в принятии решения, в том числе судьей, имеющим особое мнение.\n\n4. Исправления в решении должны быть оговорены и удостоверены подписями всех судей в совещательной комнате до объявления решения.","article_title":"Статья 169. Изложение решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e5cdfb2e7c4303287eebb7d80ea583972ef11b6ae04f674f918dac6cdc4d6e5"},{"code_id":"APK_RF","article_number":"17","version_date":"2002-07-24","article_text":"1. Дела в первой инстанции арбитражного суда рассматриваются судьей единолично, если коллегиальное рассмотрение дела не предусмотрено настоящей статьей. Коллегиальное рассмотрение дел в арбитражном суде первой инстанции осуществляется в составе трех судей или судьи и двух арбитражных заседателей.\n\n2. В первой инстанции арбитражного суда коллегиальным составом судей рассматриваются:\n\n1) (Пункт утратил силу - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\n2) дела об оспаривании нормативных правовых актов;\n\n3) (Пункт утратил силу - Федеральный закон от 12.07.2011 № 210-ФЗ)\n\n4) дела, направленные в арбитражный суд первой инстанции на новое рассмотрение с указанием на коллегиальное рассмотрение;\n\n5) дела, решения о коллегиальном рассмотрении которых приняты председателем судебного состава в связи с их особой сложностью на основании мотивированного заявления судьи; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6) дела, относящиеся к подсудности Суда по интеллектуальным правам. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n3. Арбитражный суд первой инстанции в составе судьи и двух арбитражных заседателей рассматривает экономические споры и иные дела, возникающие из гражданских и иных правоотношений, если какая-либо из сторон заявит ходатайство о рассмотрении дела с участием арбитражных заседателей.\n\nНе подлежат рассмотрению с участием арбитражных заседателей дела, предусмотренные частью 2 настоящей статьи, а также дела, возникающие из административных и иных публичных правоотношений, и дела особого производства.\n\n4. Дела в арбитражном суде апелляционной и кассационной инстанций, а также в порядке надзора рассматриваются коллегиально в составе трех или иного нечетного количества судей, если иное не установлено настоящим Кодексом.\n\nПри коллегиальном рассмотрении дела один из судей председательствует в судебном заседании.\n\n5. В случае, если настоящим Кодексом судье предоставлено право единолично рассматривать дела и разрешать отдельные процессуальные вопросы, судья действует от имени арбитражного суда.","article_title":"Статья 17. Единоличное и коллегиальное рассмотрение дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e90baa7722ef0beb1bb3b359abb162c4d52e076a5c1788afb711978a50a3cc21"},{"code_id":"APK_RF","article_number":"170","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда должно состоять из вводной, описательной, мотивировочной и резолютивной частей.\n\n2. Вводная часть решения должна содержать наименование арбитражного суда, принявшего решение; состав суда, фамилию лица, которое вело протокол судебного заседания; номер дела, дату и место принятия решения; предмет спора; наименования лиц, участвующих в деле, фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий.\n\n3. Описательная часть решения должна содержать краткое изложение заявленных требований и возражений, объяснений, заявлений и ходатайств лиц, участвующих в деле.\n\n4. В мотивировочной части решения должны быть указаны:\n\n1) фактические и иные обстоятельства дела, установленные арбитражным судом;\n\n2) доказательства, на которых основаны выводы суда об обстоятельствах дела и доводы в пользу принятого решения; мотивы, по которым суд отверг те или иные доказательства, принял или отклонил приведенные в обоснование своих требований и возражений доводы лиц, участвующих в деле;\n\n3) законы и иные нормативные правовые акты, которыми руководствовался суд при принятии решения, и мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле.\n\nВ мотивировочной части решения должны содержаться также обоснования принятых судом решений и обоснования по другим вопросам, указанным в части 5 настоящей статьи.\n\nВ случае признания иска ответчиком в мотивировочной части решения может быть указано только на признание иска и принятие его судом.\n\nВ случае отказа в иске в связи с признанием неуважительными причин пропуска срока исковой давности или срока обращения в суд в мотивировочной части решения суда указывается только на установление судом данных обстоятельств.\n\nВ мотивировочной части решения могут содержаться ссылки на постановления Пленума Верховного Суда Российской Федерации и сохранившие силу постановления Пленума Высшего Арбитражного Суда Российской Федерации по вопросам судебной практики, на постановления Президиума Верховного Суда Российской Федерации и сохранившие силу постановления Президиума Высшего Арбитражного Суда Российской Федерации, а также на обзоры судебной практики Верховного Суда Российской Федерации, утвержденные Президиумом Верховного Суда Российской Федерации.\n\n(Часть в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nПри полном или частичном удовлетворении первоначального и встречного исков в резолютивной части решения указывается денежная сумма, подлежащая взысканию в результате зачета.\n\nЕсли арбитражный суд установил порядок исполнения решения или принял меры по обеспечению его исполнения, на это указывается в резолютивной части решения.","article_title":"Статья 170. Содержание решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11b84412950acdc75ecbd7612b4564c0f87fecf83cab11f770c00b76e390f336"},{"code_id":"APK_RF","article_number":"171","version_date":"2002-07-24","article_text":"1. При удовлетворении требования о взыскании денежных средств в резолютивной части решения арбитражный суд указывает общий размер подлежащих взысканию денежных сумм с раздельным определением основной задолженности, убытков, неустойки (штрафа, пеней) и процентов.\n\n2. При присуждении имущества арбитражный суд указывает наименование имущества, подлежащего передаче истцу, его стоимость и место нахождения.","article_title":"Статья 171. Решение о взыскании денежных средств и присуждении имущества","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cffde025f93253e972299cf36b7959e22ef3bc73f66ffb8b0471e38f9c693c85"},{"code_id":"APK_RF","article_number":"172","version_date":"2002-07-24","article_text":"При удовлетворении требования относительно спора о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, в том числе на основании исполнительной надписи нотариуса, в резолютивной части решения арбитражный суд указывает наименование, номер, дату выдачи документа, не подлежащего исполнению, и денежную сумму, не подлежащую списанию.","article_title":"Статья 172. Решение о признании не подлежащим исполнению исполнительного или иного документа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad4ef4ad5ee013285735b937e4040514a420f538b5b079a5f0f26f936092a5ce"},{"code_id":"APK_RF","article_number":"173","version_date":"2002-07-24","article_text":"По спору, возникшему при заключении или изменении договора, в резолютивной части решения указывается вывод арбитражного суда по каждому спорному условию договора, а по спору о понуждении заключить договор указываются условия, на которых стороны обязаны заключить договор.","article_title":"Статья 173. Решение о заключении или об изменении договора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c1fad081c2def206fc15796f0f83f010825ceab9df5275f21d8894a8e521556"},{"code_id":"APK_RF","article_number":"174","version_date":"2002-07-24","article_text":"1. При принятии решения, обязывающего ответчика совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения указывает лицо, обязанное совершить эти действия, а также место и срок их совершения.\n\n2. При принятии решения, обязывающего организацию совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения может указать руководителя или иное лицо, на которых возлагается исполнение решения, а также срок исполнения.\n\n3. Арбитражный суд может указать в решении, что истец вправе осуществить соответствующие действия за счет ответчика со взысканием с него необходимых расходов в случае, если ответчик не исполнит решение в течение установленного срока.","article_title":"Статья 174. Решение, обязывающее ответчика совершить определенные действия","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"389d2d8778f75e1f71373a78b6adddc0447baee9e6c922a946bfc3ce0651aa82"},{"code_id":"APK_RF","article_number":"175","version_date":"2002-07-24","article_text":"1. При принятии решения в пользу нескольких истцов арбитражный суд указывает, в какой части (доле) оно относится к каждому из них, или указывает, что право требования является солидарным.\n\n2. При принятии решения против нескольких ответчиков арбитражный суд указывает, в какой части (доле) каждый из ответчиков должен выполнить решение, или указывает, что их ответственность является солидарной.","article_title":"Статья 175. Решение в пользу нескольких истцов или против нескольких ответчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3b9a6e8651fe7ac60d967958e7991ff6748f9aaf42e22c94e4aa39fd265ca99"},{"code_id":"APK_RF","article_number":"176","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда объявляется председательствующим в том судебном заседании, в котором закончено рассмотрение дела по существу, после принятия решения арбитражного суда.\n\n2. В судебном заседании, в котором закончено рассмотрение дела по существу, может быть объявлена только резолютивная часть принятого решения. В этом случае арбитражный суд объявляет, когда будет изготовлено решение в полном объеме и разъясняет порядок доведения его до сведения лиц, участвующих в деле.\n\nИзготовление решения в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления решения в полном объеме считается датой принятия решения. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n3. Объявленная резолютивная часть решения должна быть подписана всеми судьями, участвовавшими в рассмотрении дела и принятии решения, и приобщена к делу.\n\nПри выполнении резолютивной части решения в форме электронного документа дополнительно выполняется экземпляр данной резолютивной части решения на бумажном носителе, который также приобщается к делу. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n4. Председательствующий в судебном заседании после объявления решения разъясняет порядок его обжалования.","article_title":"Статья 176. Объявление решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2c64f4f2fe285eb406fbb6e5391387cb5c03d0f14fb8eb57b8b9371a36d80f2"},{"code_id":"APK_RF","article_number":"177","version_date":"2002-07-24","article_text":"1. Решение, выполненное в форме электронного документа, направляется лицам, участвующим в деле, посредством его размещения в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня его принятия.\n\nРешение, выполненное в форме электронного документа, может быть также направлено лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия.\n\nПо ходатайству указанных лиц копии решения на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\nВ случае, если решение выполнено только на бумажном носителе, арбитражный суд направляет копии решения лицам, участвующим в деле, в пятидневный срок со дня принятия решения заказным письмом с уведомлением о вручении или вручает им под расписку.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые предусмотрены настоящим Кодексом, арбитражный суд направляет копии решения и иным лицам.\n\n3. Повторная выдача копий решения и других судебных актов лицам, участвующим в деле, оплачивается государственной пошлиной.","article_title":"Статья 177. Направление решения лицам, участвующим в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb9f05bd05903f457040387b68b7dbbc9198b64c026d83321e6bebb32453aa4d"},{"code_id":"APK_RF","article_number":"178","version_date":"2002-07-24","article_text":"1. Арбитражный суд, принявший решение, до вступления этого решения в законную силу по своей инициативе или по заявлению лица, участвующего в деле, вправе принять дополнительное решение в случае, если:\n\n1) по какому-либо требованию, в отношении которого лица, участвующие в деле, представили доказательства, судом не было принято решение;\n\n2) суд, разрешив вопрос о праве, не указал в решении размер присужденной денежной суммы, подлежащее передаче имущество или не указал действия, которые обязан совершить ответчик;\n\n3) судом не разрешен вопрос о судебных расходах.\n\n2. Вопрос о принятии арбитражным судом дополнительного решения разрешается в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания. Неявка надлежащим образом извещенных лиц не препятствует рассмотрению вопроса о принятии дополнительного решения.\n\n3. Дополнительное решение принимается по правилам, установленным в настоящей главе.\n\n4. В случае отказа в принятии дополнительного решения выносится определение.\n\n5. Дополнительное решение арбитражного суда и определение арбитражного суда об отказе в принятии дополнительного решения могут быть обжалованы.","article_title":"Статья 178. Дополнительное решение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24d16dd8487eb02d8091a6312d3f2580a7959c187e96000755fa4f9eae1b7616"},{"code_id":"APK_RF","article_number":"179","version_date":"2002-07-24","article_text":"1. В случае неясности решения арбитражный суд, принявший это решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации вправе разъяснить решение без изменения его содержания.\n\n2. Разъяснение решения допускается, если оно не приведено в исполнение и не истек срок, в течение которого решение может быть принудительно исполнено.\n\n3. Арбитражный суд, принявший решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации или по своей инициативе вправе исправить допущенные в решении описки, опечатки и арифметические ошибки без изменения его содержания.","article_title":"Статья 179. Разъяснение решения. Исправление описок, опечаток и арифметических ошибок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06cfafe55c4d5c1bce7f9682b77241e5f860798d474746bfd080e708ce8b62e6"},{"code_id":"APK_RF","article_number":"18","version_date":"2002-07-24","article_text":"1) заявленного и удовлетворенного в порядке, установленном настоящим Кодексом, самоотвода или отвода судьи, арбитражного заседателя;\n\n2) длительного отсутствия судьи, арбитражного заседателя ввиду болезни, отпуска, пребывания на учебе, нахождения в служебной командировке.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 18. Формирование состава суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f22af3542bac4229a7b8375dff4f041426c51e1b21df47ed6b63ff02452cf1b9"},{"code_id":"APK_RF","article_number":"180","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда первой инстанции, за исключением решений, указанных в частях 2 и 3 настоящей статьи, вступает в законную силу по истечении месячного срока со дня его принятия, если не подана апелляционная жалоба. В случае подачи апелляционной жалобы решение, если оно не отменено и не изменено, вступает в законную силу со дня принятия постановления арбитражного суда апелляционной инстанции.","article_title":"Статья 180. Вступление в законную силу решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdfeed76172280c8e02c26e1c3afa125b25ae5087ff01cc110ed664e8fbf014d"},{"code_id":"APK_RF","article_number":"181","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 181. Обжалование решения арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dcb8aa602e92c57e5152bcb95c6af95dbb96cc7240b502c878aacb65ed6813c"},{"code_id":"APK_RF","article_number":"182","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда приводится в исполнение после вступления его в законную силу, за исключением случаев немедленного исполнения, в порядке, установленном настоящим Кодексом и иными федеральными законами, регулирующими вопросы исполнительного производства.\n\nКопии определения направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.","article_title":"Статья 182. Исполнение решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8a97fbb5924a665e6172ad474d06ecd777e77361b53cbf8ccd6463f605a9777"},{"code_id":"APK_RF","article_number":"183","version_date":"2002-07-24","article_text":"1. По заявлению взыскателя или должника арбитражный суд первой инстанции, рассмотревший дело, производит индексацию присужденных судом денежных сумм на день исполнения решения суда.\n\nЕсли иное не предусмотрено федеральным законом, присужденные денежные суммы индексируются со дня вынесения решения суда или, если решением суда предусмотрена выплата присужденной денежной суммы в предстоящем периоде, с момента, когда такая выплата должна была быть произведена.\n\nЕсли иное не предусмотрено федеральным законом или договором, для индексации используется официальная статистическая информация об индексе потребительских цен (тарифов) на товары и услуги в Российской Федерации, размещаемая на официальном сайте федерального органа исполнительной власти, осуществляющего функции по формированию официальной статистической информации о социальных, экономических, демографических, экологических и других общественных процессах в Российской Федерации, в информационно-телекоммуникационной сети \"Интернет\".\n\nЗаявление об индексации присужденных судом денежных сумм может быть подано в срок, не превышающий одного года со дня исполнения должником судебного акта. При наличии уважительных причин указанный срок может быть восстановлен арбитражным судом в порядке, предусмотренном статьей 117 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 01.04.2025 № 54-ФЗ)\n\n(Часть в редакции Федерального закона от 11.06.2022 № 177-ФЗ)\n\nПо результатам рассмотрения заявления выносится определение.","article_title":"Статья 183. Индексация присужденных денежных сумм","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a74c81ef6fc8e25030e49acd98ddb20aa1435b8df238680667d5bc4d27f8b3a"},{"code_id":"APK_RF","article_number":"184","version_date":"2002-07-24","article_text":"1. Арбитражный суд выносит определения в случаях, предусмотренных настоящим Кодексом, и в других случаях по вопросам, требующим разрешения в ходе судебного разбирательства.\n\n2. Определение выносится арбитражным судом в виде отдельного судебного акта или протокольного определения.\n\nОпределение арбитражного суда в виде отдельного судебного акта выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения определения в форме электронного документа определение выполняется на бумажном носителе.\n\nПри выполнении определения в форме электронного документа дополнительно выполняется экземпляр данного определения на бумажном носителе.\n\nИзготовление определения арбитражного суда в виде отдельного судебного акта в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления определения в полном объеме считается датой вынесения определения. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n3. Определение в виде отдельного судебного акта арбитражный суд выносит во всех случаях, если настоящим Кодексом предусмотрена возможность обжалования определения отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу.\n\nВ других случаях арбитражный суд вправе вынести определение как в виде отдельного судебного акта, так и в виде протокольного определения.\n\n4. Определение в виде отдельного судебного акта арбитражный суд выносит в условиях, обеспечивающих тайну совещания судей, по правилам, установленным для принятия решения.\n\n5. Протокольное определение может быть вынесено арбитражным судом без удаления из зала судебного заседания. В случае, если дело рассматривается в коллегиальном составе, судьи совещаются по вопросам, связанным с вынесением такого определения, на месте, в зале судебного заседания. Протокольное определение объявляется устно и заносится в протокол судебного заседания.","article_title":"Статья 184. Вынесение арбитражным судом определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed3dce08b6f2b2c3f530a53813a8f59725a3085fc619728f2f7897274fb6470b"},{"code_id":"APK_RF","article_number":"185","version_date":"2002-07-24","article_text":"1. В определении должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) наименование арбитражного суда, состав суда, фамилия лица, которое вело протокол судебного заседания;\n\n3) наименование и номер дела;\n\n4) наименования лиц, участвующих в деле;\n\n5) вопрос, по которому выносится определение;\n\n6) мотивы, по которым арбитражный суд пришел к своим выводам, принял или отклонил доводы лиц, участвующих в деле, со ссылкой на законы и иные нормативные правовые акты;\n\n7) вывод по результатам рассмотрения судом вопроса;\n\n8) порядок и срок обжалования определения.\n\nОпределение, выносимое в виде отдельного судебного акта, подписывается судьей или составом арбитражного суда, вынесшими это определение.\n\n2. В протокольном определении должны быть указаны вопрос, по которому выносится определение, мотивы, по которым суд пришел к своим выводам, и вывод по результатам рассмотрения вопроса.","article_title":"Статья 185. Содержание определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24296633569fa6d0bfc3e53b7a115d26bbb77084659cccf684e5f5f3973e53f2"},{"code_id":"APK_RF","article_number":"186","version_date":"2002-07-24","article_text":"По ходатайству указанных лиц копии определения, вынесенного в виде отдельного судебного акта, на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 186. Направление определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7aea92f8ff702dc7acbede80c0203e30c9e7ecba1963b9a5cb7cc5fcb081ad8e"},{"code_id":"APK_RF","article_number":"187","version_date":"2002-07-24","article_text":"Определение, вынесенное арбитражным судом, исполняется немедленно, если иное не установлено настоящим Кодексом или арбитражным судом.","article_title":"Статья 187. Исполнение определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fee8902cadeb4daeaa6691b9e45cfb82d0722734a88188a7ddac68297592433c"},{"code_id":"APK_RF","article_number":"188","version_date":"2002-07-24","article_text":"1. Определение арбитражного суда может быть обжаловано отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу, в случаях, если в соответствии с настоящим Кодексом предусмотрено обжалование этого определения, а также если это определение препятствует дальнейшему движению дела.\n\n2. В отношении определения, обжалование которого не предусмотрено настоящим Кодексом, а также в отношении протокольного определения могут быть заявлены возражения при обжаловании судебного акта, которым заканчивается рассмотрение дела по существу.","article_title":"Статья 188. Порядок и сроки обжалования определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8c8f386c2b49a325de8de4751d893203b6326dbe35e8925a20475712207fcc5"},{"code_id":"APK_RF","article_number":"188.1","version_date":"2002-07-24","article_text":"1. При выявлении в ходе рассмотрения дела случаев, требующих устранения нарушения законодательства Российской Федерации государственным органом, органом местного самоуправления, иным органом, организацией, наделенной федеральным законом отдельными государственными или иными публичными полномочиями, должностным лицом, адвокатом, субъектом профессиональной деятельности, арбитражный суд вправе вынести частное определение.\n\n2. Частное определение арбитражного суда направляется в соответствующий орган, организацию, наделенную федеральным законом отдельными государственными или иными публичными полномочиями, должностному лицу, а в случае нарушения законодательства Российской Федерации адвокатом, субъектом профессиональной деятельности - соответственно в адвокатское образование, саморегулируемую организацию, которые в течение месяца со дня его получения обязаны сообщить о принятых ими мерах.\n\n3. Неисполнение частного определения арбитражного суда влечет за собой ответственность, предусмотренную законодательством Российской Федерации. Привлечение к ответственности указанных в части 1 настоящей статьи лиц не освобождает их от обязанности сообщить о мерах, принятых по частному определению арбитражного суда.\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\nРАЗДЕЛ III. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ ПО ДЕЛАМ, ВОЗНИКАЮЩИМ ИЗ АДМИНИСТРАТИВНЫХ И ИНЫХ ПУБЛИЧНЫХ ПРАВООТНОШЕНИЙ","article_title":"Статья 188.1. Частные определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40ff5a749a66f2812609e843fa58d4d72d378d2c22a78c4202fb1584ec9d9539"}]$law7d0005$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
